import{_ as a,o,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Persistência e recuperação durável","description":"","frontmatter":{"title":"Persistência e recuperação durável","docId":"developer.storage","translationKey":"developer.storage","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","translationRevision":"ec562530a5513fb8a55704391bfc9741d0e19ab49ed4e16fedac4423eca1a95b","order":60},"headers":[],"relativePath":"pt/developer/storage.md","filePath":"pt/developer/storage.md","lastUpdated":1794611623000}'),r={name:"pt/developer/storage.md"};function t(d,e,n,l,c,p){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="persistence-and-durable-recovery" tabindex="-1">Persistência e recuperação durável <a class="header-anchor" href="#persistence-and-durable-recovery" aria-label="Permalink to &quot;Persistência e recuperação durável {#persistence-and-durable-recovery}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Altere estado persistente pelo serviço responsável e preserve resultados recuperáveis. Use um perfil descartável, feche seu host antes de copiar bancos de dados e leia <a href="./control-api.html">metadados de controle</a> antes de editar recursos versionados. <code>TIKTOOLS_HOME</code> seleciona a raiz do aplicativo; <code>AppPaths</code> resolve seus dados e armazenamentos privados.</p><h2 id="identify-the-store" tabindex="-1">Identifique o armazenamento <a class="header-anchor" href="#identify-the-store" aria-label="Permalink to &quot;Identifique o armazenamento {#identify-the-store}&quot;">​</a></h2><p><code>crates/tiktools-core/src/paths.rs</code> define <code>data/tiktok-points.db</code>, <code>data/tiktok-automation.db</code> e <code>data/tiktok-analytics.db</code>. Os módulos de serviço SQLite são responsáveis por seus esquemas. Pontos/espectadores e definições de automação têm registros de negócio separados; análises usam um banco distinto, omitido em diagramas antigos de dois bancos.</p><p>A inicialização pode copiar bancos legados locais do checkout para os dados de aplicativo da plataforma somente quando o destino estiver ausente. Ela nunca sobrescreve um destino existente. Definições JSON continuam legíveis durante alterações na execução nativa. Não implemente migração excluindo o perfil do usuário nem reescrevendo tabelas a partir do Vue.</p><h2 id="make-a-recoverable-change" tabindex="-1">Faça uma alteração recuperável <a class="header-anchor" href="#make-a-recoverable-change" aria-label="Permalink to &quot;Faça uma alteração recuperável {#make-a-recoverable-change}&quot;">​</a></h2><ol><li>Localize a transação do serviço e seus testes de esquema/migração.</li><li>Armazene a alteração de negócio, revisão e reserva obrigatória de diário/outbox na mesma transação quando o domínio permitir.</li><li>Preserve marcadores de exclusão de revisão. Um ID de registro reutilizado não deve aceitar uma revisão de edição anterior à exclusão.</li><li>Publique metadados de invalidação confirmados pela outbox existente; uma nova tentativa de entrega não deve repetir a ação subjacente.</li><li>Reabra o mesmo diretório privado de teste após uma interrupção e resolva o comando original antes de tentar outra mutação.</li></ol><p>Verificações úteis somente de leitura em um host de teste já em execução:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Diários duráveis de fluxos, pontos e proprietário compatíveis mantêm os resultados originais após reiniciar. Um recibo descreve seu comando histórico; leia o estado atual separadamente. Armazenamentos de workspace do Cloud adicionam partições de origem/conta e verificações de geração; não substituem a autoridade SQLite local. Nem todo efeito externo ou domínio tem a mesma cobertura de recuperação durável.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Mantenha arquivos SQLite e quaisquer WAL/SHM ativos juntos ao fazer um backup offline. Um tempo limite da interface não comprova reversão. Em <code>revision_conflict</code>, preserve o rascunho e compare uma leitura nova. Para efeitos externos incertos, inspecione o registro de efeito mantido em vez de reproduzir um feed. Consulte a <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/paths.rs" target="_blank" rel="noreferrer">autoridade de caminhos</a> e a <a href="./cloud.html">recuperação do Cloud</a> para seus limites distintos.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Confira caminhos antes de testes/cópias com <code>tiktools api call system.info --json</code>. <code>TIKTOOLS_HOME</code> escolhe a raiz; <code>TIKTOOLS_DATA_DIR</code>, <code>TIKTOOLS_PLUGINS_DIR</code>, <code>TIKTOOLS_PLUGIN_DATA_DIR</code>, <code>TIKTOOLS_PLUGIN_STORE_DIR</code>, <code>TIKTOOLS_LOG_DIR</code> e <code>TIKTOOLS_TEMP_DIR</code> substituem diretórios derivados. Valores relativos usam o diretório de inicialização. Uma raiz isolada não neutraliza overrides herdados: confira/remova-os antes.</p><p>Analytics contém agregados com escritor próprio: fila atual 1.024, lotes 128, prazo de flush 10 s. O arquivo vizinho <code>*.pending.json</code> deriva do caminho da base. A inicialização reaplica lotes identificados e remove o arquivo antes de <code>ready</code> admitir trabalho. Recuperação ilegível/acima de 16 MiB, base indisponível ou falha ao remover o arquivo mantêm admissão desativada. Preserve base e arquivo, inspecione <code>ready</code>/pendências/erros e faça backup antes do reparo. Não apague evidências para aparentar saúde; os diários de pontos têm outro contrato de durabilidade.</p><p><code>system.info</code> informa home/dataDir efetivos; resolva outros diretórios pelo ambiente real de inicialização do host, não outro terminal. Use <code>system.health</code> para ready/pendências analíticas e contadores de entrada LIVE.</p>`,18)])])}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
